"""Supplement to measure.py: the two difference-ledger rows measure.py does not
report - cards carrying a real drop shadow, and real photographs (bitmap sources,
including background-image url()s without a file extension, which is how the
example sites load their Unsplash photography).

    python measure_extra.py <url> [<url> ...]
"""
import asyncio
import json
import sys

from playwright.async_api import async_playwright

PROBE = r"""
() => {
  const main = document.querySelector('main') || document.body;
  const vis = [...main.querySelectorAll('*')].filter(el => {
    const r = el.getBoundingClientRect(); const s = getComputedStyle(el);
    return r.width > 0 && r.height > 0 && s.visibility !== 'hidden' && s.display !== 'none';
  });

  // a "card": a box >= 120x80 carrying a non-inset drop shadow
  const shadowCards = vis.filter(el => {
    const s = getComputedStyle(el); const r = el.getBoundingClientRect();
    if (!s.boxShadow || s.boxShadow === 'none' || s.boxShadow.includes('inset')) return false;
    return r.width >= 120 && r.height >= 80;
  });

  // a real photograph = a bitmap the page loads: an <img> whose source is not an
  // SVG, or a background-image url() that is not an inline SVG / data URI.
  const notSvg = u => u && !/^data:image\/svg/.test(u) && !/\.svg(\?|$)/i.test(u);
  const imgs = [...main.querySelectorAll('img')].filter(i => notSvg(i.currentSrc || i.src || ''));
  const bgPhotos = vis.filter(el => {
    const bi = getComputedStyle(el).backgroundImage;
    if (!bi || bi === 'none') return false;
    const urls = [...bi.matchAll(/url\((['"]?)([^'")]+)\1\)/g)].map(m => m[2]);
    return urls.some(notSvg);
  });

  // chromatic colours actually painted: any computed colour whose channels
  // spread more than 18/255, counted distinctly. Neutrals collapse out.
  const chroma = new Set();
  for (const el of vis) {
    const s = getComputedStyle(el);
    for (const v of [s.color, s.backgroundColor, s.borderTopColor, s.borderBottomColor]) {
      const m = (v || '').match(/rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?/);
      if (!m) continue;
      if (m[4] !== undefined && parseFloat(m[4]) === 0) continue;
      const r = +m[1], g = +m[2], b = +m[3];
      if (Math.max(r, g, b) - Math.min(r, g, b) > 18) chroma.add(`rgb(${r}, ${g}, ${b})`);
    }
  }

  return {
    shadowedCards: shadowCards.length,
    shadowSamples: shadowCards.slice(0, 4).map(el =>
      el.tagName.toLowerCase() + '.' + (el.className || '').toString().split(' ').slice(0, 2).join('.')),
    photoImgTags: imgs.length,
    photoBackgroundElements: bgPhotos.length,
    realPhotographs: imgs.length + bgPhotos.length,
    chromaticColours: chroma.size,
    chromaticList: [...chroma].sort(),
    gradientElements: vis.filter(el => /gradient/.test(getComputedStyle(el).backgroundImage || '')).length,
  };
}
"""


async def main(urls):
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        page = await browser.new_page(viewport={"width": 1440, "height": 900},
                                      reduced_motion="reduce")
        out = {}
        for url in urls:
            await page.goto(url, wait_until="networkidle", timeout=60000)
            await page.wait_for_timeout(1500)
            out[url] = await page.evaluate(PROBE)
        await browser.close()
        print(json.dumps(out, indent=2, ensure_ascii=False))


if __name__ == "__main__":
    asyncio.run(main(sys.argv[1:]))

