// Chrome serialises oklch()/lab() colours verbatim rather than as rgb(), so
// every value is normalised through a canvas before it is compared - without
// this an entirely oklch-authored page measures as zero colours.
const cx = document.createElement('canvas').getContext('2d');
const toRgb = (v) => {
  if (!v || v === 'transparent' || /rgba?\([^)]*,\s*0\)$/.test(v)) return null;
  try { cx.fillStyle = '#000'; cx.fillStyle = v; } catch (e) { return null; }
