// Chrome preserves the authored colour space, so a computed value is either
// legacy 'rgb(r, g, b)' or 'oklch(L C H)'. Both are read on their own terms:
// for rgb the channel spread, for oklch the chroma component itself. A canvas
// round-trip does NOT normalise oklch (verified: it returns the string back),
// which is why this parses rather than converts.
const isChromatic = (v) => {
  if (!v || v === 'transparent') return null;
  let m = /^oklch\(\s*([\d.]+%?)\s+([\d.]+)\s+([\d.]+)/.exec(v);
  if (m) return parseFloat(m[2]) > 0.03 ? `oklch ${m[1]} ${m[2]} ${m[3]}` : null;
  m = /^rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?/.exec(v);
  if (!m) return null;
  if (m[4] !== undefined && parseFloat(m[4]) === 0) return null;
  const r = +m[1], g = +m[2], b = +m[3];
  return Math.max(r, g, b) - Math.min(r, g, b) > 18 ? `rgb(${r}, ${g}, ${b})` : null;
};
const chroma = new Set();
for (const el of vis) {
  const s = getComputedStyle(el);
  for (const v of [s.color, s.backgroundColor, s.borderTopColor, s.borderBottomColor]) {
    const key = isChromatic(v);
    if (key) chroma.add(key);
  }
}
